#!/usr/bin/env python3
"""s35 「연못 마을」 신규 장면 + s35p01 「연못 하나」 — 하디-바인베르크 평형.

왜 이 자리인가
  J게이트(진화와 집단유전)는 157장 중 20장(12.7%)만 걸려 있고 **장면이 하나도 없었다.**
  방법론평가 v12 가 이미 「4위 · J게이트 1장면 — 유일한 완전 공백」으로 지목한 자리다.
  그림작업큐 공백순위에서도 J1-1~30 이 미연결 43장으로 2위였다.

기출이 이 패널의 형태를 정해 줬다
  5조건은 **네 번 넘게** 나왔고 전부 「~가 아닌 것 / 틀린 것」 형식이다
  (BM하 #1096·#1101·#1102·#1103). 즉 외울 것은 다섯 항목이 아니라
  **다섯 개가 전부 「하지 않는다」로 놓여 있다**는 상태 자체다.
  그래서 둘레의 장치를 전부 **꺼짐·닫힘·엎어짐·눈가림**으로 그렸다 — 하나만 켜져도 진화다.

  계산은 한 가지 형태뿐이다(#1094·#1095·#1099·#1100).
  열성 형질의 빈도 = q² → √ → q → p = 1−q → 보인자 = 2pq.
  그래서 네 칸 판에서 **흰 구슬 둘뿐인 칸이 유일하게 겉으로 드러나는 칸**임을 행으로 세웠다.

소품 ↔ 조건
  끝이 안 보이는 연못   → ④ 집단 크기 무한대
  눈을 가린 사람        → ② 무작위 교배
  레버 내려간 페인트 기계 → ① 돌연변이 없음
  엎어 놓은 체          → ③ 자연선택 없음
  판을 내려 닫은 수문    → ⑤ 유전자 흐름 없음
  네 칸 판             → p² + 2pq + q² (다른 색 짝이 두 칸인 것이 2pq 의 2)
"""
import os, re, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SK = os.path.join(ROOT, 'sketchy.html')

BR = ('연못 하나가 <b>집단</b>이고 그 안의 구슬 전부가 <b>유전자 풀</b>이다. 개체는 진화하지 않는다 — '
      '<b>연못 안의 비율</b>이 변하는 것이 진화다. 둘레의 장치 넷이 전부 「하지 않는다」로 놓여 있는데, '
      '<b>하나만 풀려도 그 집단은 진화한다</b>.')

BX = """<p><b>연못이 단위다.</b> 흔한 오해가 「개체가 진화한다」인데, 구슬 하나는 색이 변하지 않는다. 변하는 것은 <b>연못 안의 비율</b>이고, 그것이 <b>미시진화</b> — 세대에 걸친 대립유전자 빈도의 변화 — 다. 가뭄 뒤 핀치의 부리가 커진 것도 새 한 마리의 부리가 자란 것이 아니라 <b>큰 부리 개체의 비율</b>이 늘어난 것이다.</p><p><b>식 둘은 같은 말이다.</b> 색이 둘뿐이니 <b>p + q = 1</b>이고, 그 둘에서 짝을 지으면 <b>p² + 2pq + q² = 1</b>이 된다. 네 칸 판에서 <b>다른 색 짝이 두 칸</b>인 것이 2pq 의 <b>2</b>다 — 검-흰과 흰-검, 두 가지 방법으로 만들어지기 때문이다. 유전자 풀을 아무리 섞어도 <b>대립유전자 빈도 자체는 안 변한다</b>(카드덱을 아무리 섞어도 카드 구성은 그대로다).</p><p><b>다섯 조건은 전부 「하지 않는다」다.</b> 그래서 기출이 늘 <b>「조건이 아닌 것」·「틀린 것」</b>으로 묻는다. 「자연선택이 발생해야 한다」·「특정한 교접이 일어난다」·「자연선택이 작용한다고 가정한다」·「돌연변이가 존재함을 전제로 한다」 — 넷 다 실제로 나온 오답 선지이고, 넷 다 <b>「한다」로 뒤집은 문장</b>이다. 그림 둘레가 전부 꺼짐·닫힘·엎어짐·눈가림인 것이 이 뜻이다.</p><p><b>평형은 목표가 아니라 자다.</b> 실제 자연 집단은 이 조건을 다 채우지 못한다. 평형식은 「진화하지 않는다면 어떤 빈도일까」를 재는 <b>기준점</b>이고, 관찰값이 기댓값과 다르면 <b>진화가 일어나고 있다는 신호</b>다.</p><p><b>계산은 늘 오른쪽 아래 칸에서 시작한다.</b> 겉으로 세어지는 것은 열성 형질뿐이고 그것이 <b>q²</b>다. 제곱근을 씌워 q 를 얻고, p = 1 − q 로 넘어가, 보인자를 <b>2pq</b>로 답한다. 기출은 이 한 줄을 숫자만 바꿔 반복한다.</p><div class='qx'><div class='qh'>여기서 갈리는 문제</div><p class='qlead'>조건 문제는 <b>「아니다」를 고르는 문제</b>다. 선지 다섯 중 넷은 「~가 없어야 한다」인데 하나만 「~가 일어나야 한다/작용한다」로 뒤집혀 있다. 다섯을 외우려 하지 말고 <b>혼자 「한다」로 되어 있는 것</b>을 찾으면 된다. 계산 문제는 발문이 늘 「열성 질환이 N명 중 M명」으로 시작한다 — 그 수가 <b>q²</b>다.</p><details class='qitem'><summary><span class='qsrc'>BM하 #1096 · 2010</span><span class='qq'>어떤 개체군 내에서 유전자빈도가 일정하게 유지되기 위해서 필요한 조건이 아닌 것은?</span></summary><ol class='qc'><li>돌연변이가 일어나지 않아야 한다.</li><li class='ans'>자연선택이 발생해야 한다.</li><li>교배는 완전히 무작위로 행해져야 한다.</li><li>개체군이 매우 커야 한다.</li><li>개체군 안팎으로 개체들의 이입과 출입이 없어야 한다.</li></ol><div class='qa'><b>정답 ②</b> — 다섯 선지 중 <b>넷은 「없어야 한다」</b>이고 ②만 「발생해야 한다」다. 혼자 방향이 뒤집힌 것을 고르면 끝난다. 그림에서 이 넷이 각각 <b>꺼진 기계</b>(①)·<b>눈가리개</b>(③)·<b>끝이 안 보이는 연못</b>(④)·<b>닫힌 수문</b>(⑤)이고, ②에 해당하는 <b>체는 엎어져 아무것도 안 거르고 있다</b>. 자연선택이 「발생하면」 그 체가 뒤집혀 구슬을 골라내기 시작하고, 그 순간 비율이 변한다 — 그것이 진화다.<br>같은 것을 다르게 묻는 문항이 계속 나온다. <b>#1101(강원대)</b>은 「<b>특정한 교접(specific mating)이 일어난다</b>」를 틀린 선지로 냈다 — 평형의 전제는 무작위 교배이므로 눈가리개를 벗기면 안 된다. <b>#1102(건국대)</b>는 「<b>자연선택이 작용한다고 가정한다</b>」, <b>#1103(강원대)</b>은 「<b>돌연변이가 존재함을 전제로 한다</b>」를 틀린 선지로 냈다. 넷 다 같은 수법이다.</div></details><details class='qitem'><summary><span class='qsrc'>BM하 #1095 · 2009</span><span class='qq'>페닐케톤뇨증이 미국에서 신생아 1만 명 중 4명 발생하는 열성 유전질환일 때, 하디-바인베르크 법칙에 따르면 보인자는 약 몇 %인가?</span></summary><ol class='qc'><li>약 1%</li><li>약 2%</li><li>약 3%</li><li class='ans'>약 4%</li><li>약 5%</li></ol><div class='qa'><b>정답 ④</b> — 「1만 명 중 4명」이 곧 <b>q² = 4/10000 = 0.0004</b>다. 발문의 숫자를 q² 로 받는 것이 첫 걸음이고, 여기서 어긋나면 뒤가 전부 틀어진다. 제곱근을 씌워 <b>q = 0.02</b>, 이어서 <b>p = 1 − q = 0.98</b>, 보인자는 <b>2pq = 2(0.98)(0.02) = 0.0392 ≈ 4%</b>다.<br>그림의 네 칸 판이 이 순서 그대로다. 겉으로 세어지는 것은 <b>흰 구슬 둘뿐인 오른쪽 아래 칸 하나</b>(q²)이고, 구하려는 보인자는 <b>다른 색 짝 두 칸</b>(2pq)이다. 두 칸이라는 것을 놓쳐 2를 빠뜨리면 답이 절반(약 2%)이 되어 <b>②</b>로 간다 — 이 문항의 오답 배치가 정확히 그것을 노린다.<br>같은 계산이 숫자만 바꿔 반복된다. <b>#1094(2006)</b>는 1만 명 중 1명이라 q=0.01·2pq≈2%, <b>#1099(강원대)</b>는 같은 조건을 「만 명당 몇 명」으로 물어 약 200명, <b>#1100(강원대)</b>은 방향을 틀어 「O형이 36%면 O 대립인자 빈도는?」이라 <b>√0.36 = 0.6</b>이다. 발문이 <b>빈도를 묻는지 사람 수를 묻는지</b>만 마지막에 한 번 더 확인한다.</div></details><div class='qrule'>조건 문제는 <b>혼자 「한다」로 뒤집힌 선지</b>를 고른다. 계산 문제는 <b>발문의 비율이 q²</b>이고, 거기서 √ → q → p → <b>2pq</b> 순으로만 간다. 「2」를 빠뜨리는 것이 유일하고도 최대의 함정이다.</div></div>"""

ROWS = [
    ('끝이 어디인지 보이지 않는 연못 하나',
     '<b>집단</b>이 진화의 단위다. 구슬 하나는 색이 변하지 않는다 — 변하는 것은 <b>연못 안의 비율</b>이고, '
     '그것이 <b>미시진화</b>(세대에 걸친 대립유전자 빈도 변화)다',
     ['J1-1', 'J1-2']),
    ('연못을 가득 채운 구슬 전부 — 색은 딱 두 가지',
     '<b>유전자 풀</b> — 집단의 모든 대립유전자를 모은 것. 검은 구슬의 비율이 <b>p</b>, 흰 구슬이 <b>q</b>이고 '
     '색이 둘뿐이므로 <b>p + q = 1</b>이다',
     ['J1-8', 'J1-9']),
    ('그 연못이 화면 밖으로 이어져 끝이 안 보인다',
     '조건 ④ <b>집단 크기가 무한대</b>. 작으면 우연만으로 비율이 출렁인다(유전적 부동) — '
     '연못이 작을수록 그 효과가 크다',
     ['J1-13#4']),
    ('눈을 천으로 가린 채 손을 넣어 구슬을 집는 사람',
     '조건 ② <b>무작위 교배</b>. 보고 고르면 안 된다 — 「특정한 교접이 일어난다」는 평형 설명으로 <b>틀린</b> 문장이다',
     ['J1-13#2']),
    ('레버가 끝까지 내려가 꺼진 페인트 기계 · 노즐에서 아무것도 안 나온다',
     '조건 ① <b>돌연변이 없음</b>. 새 색을 칠하는 기계가 꺼져 있다 — 새 대립유전자가 생기지 않는다',
     ['J1-13#1']),
    ('엎어 놓은 채 아무것도 안 거르고 있는 체',
     '조건 ③ <b>자연선택 없음</b>. 이 체가 뒤집혀 구슬을 골라내기 시작하면 그 순간 비율이 변한다',
     ['J1-13#3']),
    ('판을 끝까지 내려 닫은 수문 · 그 너머 다른 연못의 구슬은 넘어오지 못한다',
     '조건 ⑤ <b>유전자 흐름 없음</b>. 집단 사이에 대립유전자가 오가지 않아야 한다',
     ['J1-13#5']),
    ('다섯이 전부 꺼짐·닫힘·엎어짐·눈가림이다',
     '다섯 조건은 모두 <b>「하지 않는다」</b>이고, <b>하나만 풀려도 그 집단은 진화한다</b>. '
     '그래서 기출은 늘 「조건이 아닌 것」을 묻는다 — 혼자 「한다」로 뒤집힌 선지가 답이다',
     ['J1-13', 'J1-14', 'J1-11']),
    ('이젤 위 네 칸 판 — 왼쪽 위는 검은 구슬 둘, 오른쪽 아래는 흰 구슬 둘, 나머지 두 칸은 검흰 한 쌍씩',
     '<b>p² + 2pq + q² = 1</b>. 다른 색 짝이 <b>두 칸</b>인 것이 2pq 의 <b>2</b>다 — '
     '검-흰과 흰-검, 두 가지 방법으로 만들어지기 때문이다',
     ['J1-10', 'J1-12']),
    ('네 칸 중 흰 구슬 둘뿐인 칸은 오른쪽 아래 하나뿐이다',
     '계산은 늘 여기서 시작한다. 겉으로 세어지는 것은 열성 형질뿐이고 그것이 <b>q²</b>다 — '
     '제곱근을 씌워 q, 그다음 p = 1 − q, 답은 <b>2pq</b>. 「2」를 빠뜨리면 정답의 절반이 나온다', None),
]

SCENE_HEAD = ("{id:'s35',t:'연못 마을',gate:'J',unit:'23 집단의 진화 — 하디-바인베르크와 미시진화',panels:[\n ")


def close_brace(t, i):
    op = t[i]
    cl = {'{': '}', '[': ']'}[op]
    d, q, j = 0, None, i
    while j < len(t):
        c = t[j]
        if q:
            if c == '\\':
                j += 2
                continue
            if c == q:
                q = None
        elif c in '"\'`':
            q = c
        elif c == op:
            d += 1
        elif c == cl:
            d -= 1
            if d == 0:
                return j
        j += 1
    raise SystemExit('괄호 안 닫힘')


def q2(s):
    assert '"' not in s and '\\' not in s, s
    return '"%s"' % s


def main():
    src = open(SK, encoding='utf-8').read()
    assert "{id:'s35'" not in src, '이미 있다'
    assert '`' not in BX and "'" not in BR

    # s34 장면 객체가 끝나는 자리 뒤에 새 장면을 끼운다
    i = src.index("{id:'s34',t:")
    e = close_brace(src, i)

    rows = []
    for prop, fact, cards in ROWS:
        r = '[' + q2(prop) + ',' + q2(fact)
        if cards:
            r += ',[' + ','.join(q2(c) for c in cards) + ']'
        rows.append(r + ']')

    panel = ("{id:'s35p01',t:'연못 하나',br:'" + BR + "',bx:`" + BX
             + "`,f:[" + ',\n  '.join(rows) + ']}')
    scene = SCENE_HEAD + panel + ']}'
    out = src[:e + 1] + ',\n' + scene + src[e + 1:]

    # 되읽어 확인
    k = out.index("{id:'s35p01'")
    blk = out[k:close_brace(out, k) + 1]
    ids = re.findall(r"\{id:'([sd]\d+p\d+[ab]?)'", out)
    assert len(ids) == len(set(ids)), '패널 id 중복'
    scenes = re.findall(r"\{id:'(s\d+|d\d+)',t:'[^']*',gate:", out)
    assert len(scenes) == len(set(scenes)), '장면 id 중복'
    assert 's35' in scenes, '장면 미등록'
    cards = re.findall(r'"(J1-[\w#]+)"', blk)
    assert len(cards) == len(set(cards)), '카드 중복'
    print('장면 %d개 · 패널 %d개 · s35p01 행 %d · 카드 %d장'
          % (len(scenes), len(ids), len(ROWS), len(cards)))
    print('  ' + ' '.join(cards))
    open(SK, 'w', encoding='utf-8').write(out)
    return 0


if __name__ == '__main__':
    sys.exit(main())
